macro_rules! deps {
    () => {
        Time!();
    };
}

macro_rules! all_simple_paths {
    () => {
        deps!();
        # [doc = " Calculate all simple paths with specified constraints from node `from` to node `to`."] # [doc = ""] # [doc = " A simple path is a path without repeating nodes."] # [doc = " The number of simple paths between a given pair of vertices can grow exponentially,"] # [doc = " reaching `O(|V|!)` on complete graphs with `|V|` vertices."] # [doc = ""] # [doc = " So if you have a large enough graph, be prepared to wait on the results for years."] # [doc = " Or consider extracting only part of the simple paths using the adapter [`Iterator::take`]."] # [doc = " Also note, that this algorithm does not check that a path exists between `from` and `to`. This may lead to very long running times and it may be worth it to check if a path exists before running this algorithm on large graphs."] # [doc = ""] # [doc = " This algorithm is adapted from [NetworkX](https://networkx.github.io/documentation/stable/reference/algorithms/generated/networkx.algorithms.simple_paths.all_simple_paths.html)."] # [doc = " # Arguments"] # [doc = " * `graph`: an input graph."] # [doc = " * `from`: an initial node of desired paths."] # [doc = " * `to`: a target node of desired paths."] # [doc = " * `min_intermediate_nodes`: the minimum number of nodes in the desired paths."] # [doc = " * `max_intermediate_nodes`: the maximum number of nodes in the desired paths (optional)."] # [doc = " # Returns"] # [doc = " Returns an iterator that produces all simple paths from `from` node to `to`, which contains at least `min_intermediate_nodes`"] # [doc = " and at most `max_intermediate_nodes` intermediate nodes, if given, or limited by the graph's order otherwise."] # [doc = ""] # [doc = " # Complexity"] # [doc = " * Time complexity: for computing the first **k** paths, the running time will be **O(k|V| + k|E|)**."] # [doc = " * Auxillary space: **O(|V|)**."] # [doc = ""] # [doc = " where **|V|** is the number of nodes and **|E|** is the number of edges."] # [doc = ""] # [doc = " # Example"] # [doc = " ```"] # [doc = " use std::collections::hash_map::RandomState;"] # [doc = " use petgraph::{algo, prelude::*};"] # [doc = ""] # [doc = " let mut graph = DiGraph::<&str, i32>::new();"] # [doc = ""] # [doc = " let a = graph.add_node(\"a\");"] # [doc = " let b = graph.add_node(\"b\");"] # [doc = " let c = graph.add_node(\"c\");"] # [doc = " let d = graph.add_node(\"d\");"] # [doc = ""] # [doc = " graph.extend_with_edges(&[(a, b, 1), (b, c, 1), (c, d, 1), (a, b, 1), (b, d, 1)]);"] # [doc = ""] # [doc = " let paths = algo::all_simple_paths::<Vec<_>, _, RandomState>(&graph, a, d, 0, None)"] # [doc = "   .collect::<Vec<_>>();"] # [doc = ""] # [doc = " assert_eq!(paths.len(), 4);"] # [doc = ""] # [doc = ""] # [doc = " // Take only 2 paths."] # [doc = " let paths = algo::all_simple_paths::<Vec<_>, _, RandomState>(&graph, a, d, 0, None)"] # [doc = "   .take(2)"] # [doc = "   .collect::<Vec<_>>();"] # [doc = ""] # [doc = " assert_eq!(paths.len(), 2);"] # [doc = ""] # [doc = " ```"] pub fn all_simple_paths < TargetColl , G , S > (graph : G , from : G :: NodeId , to : G :: NodeId , min_intermediate_nodes : usize , max_intermediate_nodes : Option < usize > ,) -> impl Iterator < Item = TargetColl > where G : NodeCount , G : IntoNeighborsDirected , G :: NodeId : Eq + Hash , TargetColl : FromIterator < G :: NodeId > , S : BuildHasher + Default , { let max_length = if let Some (l) = max_intermediate_nodes { l + 1 } else { graph . node_count () - 1 } ; let min_length = min_intermediate_nodes + 1 ; let mut visited : IndexSet < G :: NodeId , S > = IndexSet :: from_iter (Some (from)) ; let mut stack = vec ! [graph . neighbors_directed (from , Outgoing)] ; from_fn (move | | { while let Some (children) = stack . last_mut () { if let Some (child) = children . next () { if visited . contains (& child) { continue ; } if visited . len () < max_length { if child == to { if visited . len () >= min_length { let path = visited . iter () . cloned () . chain (Some (to)) . collect :: < TargetColl > () ; return Some (path) ; } } else { visited . insert (child) ; stack . push (graph . neighbors_directed (child , Outgoing)) ; } } else { if (child == to || children . any (| v | v == to && ! visited . contains (& v))) && visited . len () >= min_length { let path = visited . iter () . cloned () . chain (Some (to)) . collect :: < TargetColl > () ; return Some (path) ; } stack . pop () ; visited . pop () ; } } else { stack . pop () ; visited . pop () ; } } None }) }
    };
}

all_simple_paths!();